package org.transittr;

import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.view.*;import android.widget.*;
import java.util.*;import java.util.concurrent.*;import org.json.*;

/** Selected catalogue route, in the same app shell. No live bus ETA is inferred from a path. */
public final class RouteScreen {
 public interface Navigation {void back();void stop(JourneyData.Station stop);void line(CatalogStore.Item line);}
 private final Activity activity;private final int city;private final CatalogStore.Item item;private final Typeface face;private final boolean compact;private final Navigation navigation;
 private final Handler main=new Handler();private final ExecutorService worker=Executors.newSingleThreadExecutor();private final OsmMapView map;private final TextView status;private final ListView stops;private volatile boolean closed;private JourneyData.Route route;private Dialog timesDialog;
 private static final int INK=0xff141414,MUTED=0xff606460;
 public RouteScreen(Activity activity,LinearLayout body,int city,CatalogStore.Item item,Typeface face,boolean compact,Navigation navigation){
  this.activity=activity;this.city=city;this.item=item;this.face=face;this.compact=compact;this.navigation=navigation;
  LinearLayout bar=new LinearLayout(activity);bar.setPadding(dp(16),0,dp(16),0);bar.setGravity(Gravity.CENTER_VERTICAL);body.addView(bar,new LinearLayout.LayoutParams(-1,dp(48)));
  bar.addView(button("‹",new View.OnClickListener(){public void onClick(View v){RouteScreen.this.navigation.back();}}),new LinearLayout.LayoutParams(dp(44),dp(44)));
  TextView code=text(item.code,24,INK);code.setPadding(dp(12),0,0,0);bar.addView(code,new LinearLayout.LayoutParams(0,-2,1));
  bar.addView(button(city==0?"Sefer saatleri":"Bilgi",new View.OnClickListener(){public void onClick(View v){if(RouteScreen.this.city==0)times(false);else info();}}),new LinearLayout.LayoutParams(dp(city==0?122:72),dp(44)));
  TextView name=text(item.name,14,INK);name.setMaxLines(compact?1:2);name.setEllipsize(android.text.TextUtils.TruncateAt.END);name.setPadding(dp(20),dp(3),dp(20),dp(6));body.addView(name);
  status=text("Hat haritası hazırlanıyor…",12,MUTED);status.setPadding(dp(20),0,dp(20),dp(8));status.setMaxLines(2);body.addView(status);
  FrameLayout frame=new FrameLayout(activity);body.addView(frame,new LinearLayout.LayoutParams(-1,0,1));map=new OsmMapView(activity);map.metro(false);frame.addView(map,new FrameLayout.LayoutParams(-1,-1));
  map.setSelection(new OsmMapView.Selection(){public void selected(String title,String detail){info();}});
  map.setStopSelection(new OsmMapView.StopSelection(){public void selected(JourneyData.Station stop){showStop(stop);}});
  LinearLayout zoom=new LinearLayout(activity);zoom.setOrientation(1);zoom.addView(button("+",new View.OnClickListener(){public void onClick(View v){map.changeZoom(1);}}),new LinearLayout.LayoutParams(dp(44),dp(44)));LinearLayout.LayoutParams minus=new LinearLayout.LayoutParams(dp(44),dp(44));minus.topMargin=dp(4);zoom.addView(button("−",new View.OnClickListener(){public void onClick(View v){map.changeZoom(-1);}}),minus);FrameLayout.LayoutParams zp=new FrameLayout.LayoutParams(dp(44),-2,Gravity.RIGHT|Gravity.BOTTOM);zp.rightMargin=dp(12);zp.bottomMargin=dp(32);frame.addView(zoom,zp);
  TextView label=text("Duraklar",16,INK);label.setPadding(dp(20),dp(7),dp(20),dp(3));body.addView(label);stops=new ListView(activity);stops.setCacheColorHint(0xffffffff);stops.setBackgroundColor(0xffffffff);stops.setDivider(new ColorDrawable(0xffeef0ec));stops.setDividerHeight(dp(1));body.addView(stops,new LinearLayout.LayoutParams(-1,dp(compact?78:126)));
  map.center(city==0?39.9255:city==1?41.012:city==2?38.4237:37.8746,city==0?32.8538:city==1?28.976:city==2?27.1428:32.4932,12);
  load(false);
 }
 private int dp(float value){return(int)(value*activity.getResources().getDisplayMetrics().density+.5f);}
 private TextView text(String value,int size,int color){TextView t=new TextView(activity);t.setText(value);t.setTextSize(size);t.setTextColor(color);if(face!=null)t.setTypeface(face);return t;}
 private Button button(String label,View.OnClickListener action){Button b=new Button(activity);b.setText(label);b.setTextSize(compact?12:13);b.setSingleLine(true);b.setTextColor(INK);if(face!=null)b.setTypeface(face);b.setPadding(dp(8),0,dp(8),0);b.setMinWidth(0);b.setMinimumWidth(0);b.setMinHeight(dp(44));b.setMinimumHeight(dp(44));GradientDrawable background=new GradientDrawable();background.setColor(0xffffffff);background.setCornerRadius(dp(6));background.setStroke(dp(1),0xffdedfda);GradientDrawable pressed=new GradientDrawable();pressed.setColor(0xffe5e5e2);pressed.setCornerRadius(dp(6));StateListDrawable states=new StateListDrawable();states.addState(new int[]{android.R.attr.state_pressed},pressed);states.addState(new int[]{},background);b.setBackgroundDrawable(states);b.setOnClickListener(action);return b;}
 private Dialog dialog(String title){Dialog d=new Dialog(activity);d.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout box=new LinearLayout(activity);box.setOrientation(1);box.setPadding(dp(20),dp(18),dp(20),dp(16));box.setBackgroundColor(0xffffffff);box.addView(text(title,20,INK));LinearLayout content=new LinearLayout(activity);content.setOrientation(1);content.setId(7401);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.topMargin=dp(14);box.addView(content,cp);d.setContentView(box);return d;}
 private void show(Dialog d){d.show();d.getWindow().setLayout(Math.min(activity.getResources().getDisplayMetrics().widthPixels-dp(32),dp(440)),-2);}
 private void load(final boolean force){worker.execute(new Runnable(){public void run(){try{final JourneyData.Route data=RouteRepository.load(activity,city,item,force);main.post(new Runnable(){public void run(){if(closed)return;route=data;map.route(data);status.setText(data.stops.size()+" durak · "+(data.schematic?"Şematik durak bağlantısı":"Güzergâh geometrisi")+(data.mappedStops<data.stops.size()?" · "+data.mappedStops+" konum":""));JourneyData.RailLine bounds=new JourneyData.RailLine();for(ArrayList<JourneyData.Station> part:data.parts)bounds.stations.addAll(part);for(JourneyData.Station stop:data.stops)if(located(stop))bounds.stations.add(stop);if(!bounds.stations.isEmpty())map.focus(bounds);stops.setAdapter(new StopRows(data.stops));stops.setOnItemClickListener(new AdapterView.OnItemClickListener(){public void onItemClick(AdapterView<?> parent,View view,int position,long id){showStop(route.stops.get(position));}});if(data.parts.isEmpty())status.setText("Çizgi için yeterli konum yok · "+data.mappedStops+" konumlu durak");}});}catch(final Exception e){main.post(new Runnable(){public void run(){if(!closed)status.setText("Hat haritası alınamadı · yeniden açmayı dene");}});}}});}
 private boolean located(JourneyData.Station stop){return stop.lat>=35&&stop.lat<=43&&stop.lon>=25&&stop.lon<=45;}
 private void showStop(final JourneyData.Station stop){final Dialog d=dialog(stop.code.length()>0?stop.code+" · "+stop.name:stop.name);LinearLayout content=(LinearLayout)d.findViewById(7401);if(located(stop)){content.addView(button("Haritada yakınlaş",new View.OnClickListener(){public void onClick(View v){d.dismiss();map.center(stop.lat,stop.lon,16);}}),new LinearLayout.LayoutParams(-1,dp(44)));}else content.addView(text("Bu durak için koordinat verisi yok.",14,MUTED));if(city!=2&&stop.code.matches(city==0?"[0-9]{5}":city==1?"[0-9]{5,8}":"[0-9]{1,8}")){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(44));lp.topMargin=dp(8);content.addView(button("Bu durakta canlı takip",new View.OnClickListener(){public void onClick(View v){d.dismiss();navigation.stop(stop);}}),lp);}show(d);}
 private void info(){final Dialog d=dialog(item.code+" · Hat bilgisi");LinearLayout content=(LinearLayout)d.findViewById(7401);ScrollView scroll=new ScrollView(activity);String value=item.name+"\n\n"+(route==null?"Veri henüz alınamadı.":(route.schematic?"Çizgi, bilinen durakları sırayla birleştirir; gerçek yol/ray geometrisi değildir.":"Yayımlanmış güzergâh geometrisi.")+"\n\n"+route.notice+"\n\n"+route.source);scroll.addView(text(value,13,MUTED));content.addView(scroll,new LinearLayout.LayoutParams(-1,dp(compact?190:280)));content.addView(button("Yeniden yükle",new View.OnClickListener(){public void onClick(View v){d.dismiss();status.setText("Güzergâh yenileniyor…");load(true);}}),new LinearLayout.LayoutParams(-1,dp(44)));show(d);}
 private final class StopRows extends BaseAdapter {private final ArrayList<JourneyData.Station> rows;StopRows(ArrayList<JourneyData.Station> rows){this.rows=rows;}public int getCount(){return rows.size();}public Object getItem(int p){return rows.get(p);}public long getItemId(int p){return p;}public View getView(int p,View view,ViewGroup parent){TextView t=view instanceof TextView?(TextView)view:text("",13,INK);JourneyData.Station stop=rows.get(p);t.setText((stop.code.length()>0?stop.code+" · ":"")+stop.name+(located(stop)?"":" · konum yok"));t.setPadding(dp(16),dp(10),dp(16),dp(10));t.setGravity(Gravity.CENTER_VERTICAL);t.setMinimumHeight(dp(46));t.setMaxLines(2);return t;}}
 private void times(final boolean force){
  if(timesDialog!=null)timesDialog.dismiss();final Dialog d=dialog(item.code+" · Sefer saatleri");timesDialog=d;final LinearLayout content=(LinearLayout)d.findViewById(7401);final TextView updated=text("EGO saatleri okunuyor…",12,MUTED);content.addView(updated);final LinearLayout days=new LinearLayout(activity);content.addView(days,new LinearLayout.LayoutParams(-1,dp(44)));ScrollView scroll=new ScrollView(activity);final TextView entries=text("",14,INK);entries.setPadding(0,dp(10),0,dp(10));scroll.addView(entries);content.addView(scroll,new LinearLayout.LayoutParams(-1,dp(compact?190:290)));content.addView(button("EGO'dan yenile",new View.OnClickListener(){public void onClick(View v){times(true);}}),new LinearLayout.LayoutParams(-1,dp(44)));show(d);
  worker.execute(new Runnable(){public void run(){try{final JSONObject data=EgoSchedule.get(activity,item.code,force);main.post(new Runnable(){public void run(){if(closed||timesDialog!=d)return;java.text.SimpleDateFormat date=new java.text.SimpleDateFormat("dd.MM.yyyy HH:mm",Locale.US);date.setTimeZone(TimeZone.getTimeZone("GMT+03:00"));updated.setText((data.optBoolean("stale")?"Önceki kayıt · yenilenemedi · ":"EGO · eşitleme ")+date.format(new Date(data.optLong("synced_at",0))));String[] labels={"Hafta içi","Cumartesi","Pazar"};Calendar now=Calendar.getInstance(TimeZone.getTimeZone("GMT+03:00"));int day=now.get(Calendar.DAY_OF_WEEK),selected=day==Calendar.SATURDAY?1:day==Calendar.SUNDAY?2:0;try{entries.setText(EgoSchedule.description(data,selected));}catch(Exception ignored){}for(int i=0;i<3;i++){final int chosen=i;days.addView(button(labels[i],new View.OnClickListener(){public void onClick(View v){try{entries.setText(EgoSchedule.description(data,chosen));}catch(Exception ignored){}}}),new LinearLayout.LayoutParams(0,dp(44),1));}}});}catch(Exception e){main.post(new Runnable(){public void run(){if(!closed&&timesDialog==d)updated.setText("EGO saatleri şu an alınamadı.");}});}}});
 }
 public void pause(boolean value){map.pause(value);}
 public void close(){closed=true;if(timesDialog!=null)timesDialog.dismiss();map.close();main.removeCallbacksAndMessages(null);worker.shutdownNow();}
}
